package fitt_nutri.example.demo.config; import org.springframework.web.bind.annotation.ControllerAdvice; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.http.ResponseEntity; @ControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(Exception.class) public ResponseEntity<String> handleAll(Exception ex) { ex.printStackTrace(); return ResponseEntity.internalServerError().body(ex.getMessage()); } }
